    long long total = 0;
    for (int i = 1; i <= N; ++i) {
        int a;
        scanf("%d", &a);
        total += a;
        pref[i] = pref[i - 1] + a;
    }

    long long *prev = (long long *)malloc((N + 1) * sizeof(long long));
    long long *cur = (long long *)malloc((N + 1) * sizeof(long long));

    for (int i = 0; i <= N; ++i) {
        prev[i] = 0;
    }

    const long long INF = (1LL << 60);

    for (int j = 1; j <= K; ++j) {
        int lower = j * C;
        int upper = N - (K - j) * C;

